/* prog33_mod_pow – modular exponentiation with strict input validation
 *
 * The original binary implements a state‑machine that:
 *   * expects exactly three numeric arguments: base, exponent, modulus
 *   * prints "NO_INPUT" when fewer than three arguments are supplied
 *   * prints "BAD_INPUT" if any argument is not a pure decimal integer
 *       – at least one digit must be present
 *       – trailing characters are not allowed
 *       – leading whitespace is tolerated (as the original `strtoll` does)
 *   * prints "NEGATIVE_EXPONENT" when the exponent is negative
 *   * prints "BAD_MODULUS"   when the modulus is < 1
 *   * prints "OUT_OF_RANGE" when the modulus is > 1 000 000 000
 *   * computes (base^exponent) mod modulus using binary exponentiation
 *   * prints the result as:  result=%lld\n
 *
 * The implementation below follows exactly the same observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <ctype.h>

/* Validate a decimal integer string using the same rules as the original
 * program (strtoll with leading‑whitespace allowed, but the whole string
 * must be consumed). */
static int is_valid_number(const char *s, long long *out)
{
    const char *p = s;
    char *endptr;

    if (p == NULL)
        return 0;

    /* skip leading whitespace – strtoll does this automatically,
       but we need to know where the number actually starts. */
    while (isspace((unsigned char)*p))
        p++;

    if (*p == '\0')               /* no digits at all */
        return 0;

    *out = strtoll(p, &endptr, 10);

    if (p == endptr)              /* no digits were parsed */
        return 0;

    if (*endptr != '\0')          /* trailing characters */
        return 0;

    return 1;
}

int main(int argc, char **argv)
{
    long long base, exp, mod;
    long long result, base_mod;

    /* ---------- argument count ---------- */
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse and validate base ---------- */
    if (!is_valid_number(argv[1], &base)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse and validate exponent ---------- */
    if (!is_valid_number(argv[2], &exp)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- parse and validate modulus ---------- */
    if (!is_valid_number(argv[3], &mod)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- semantic checks ---------- */
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }

    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- modular exponentiation (binary method) ---------- */
    /* bring base into the range [0, mod‑1] */
    base_mod = base % mod;
    if (base_mod < 0)
        base_mod += mod;

    result = 1 % mod;   /* initialise result */

    while (exp > 0) {
        if (exp & 1LL) {
            __int128 tmp = (__int128)result * base_mod;
            result = (long long)(tmp % mod);
        }
        __int128 sq = (__int128)base_mod * base_mod;
        base_mod = (long long)(sq % mod);
        exp >>= 1;
    }

    printf("result=%lld\n", result);
    return 0;
}
